<div class="page-actions"><a class="back-link" href="<?= site_url('admin/wilayah/'.$level) ?>">← Kembali ke daftar</a></div><section class="form-panel"><div class="form-intro"><span class="panel-overline">KODE WILAYAH</span><h2><?= h($title) ?></h2><p>Gunakan kode sesuai keputusan Kemendagri. Kode induk mengikuti bagian awal kode wilayah.</p></div><form method="post" action="<?= site_url('admin/wilayah/'.$level.'/simpan') ?>"><?= csrf_input() ?><input type="hidden" name="id" value="<?= h($region['id']??'') ?>"><div class="form-grid"><label>Kode resmi <span class="required">*</span><input name="code" value="<?= h($region['code']??'') ?>" required placeholder="<?= $level==='village'?'33.17.01.2001':($level==='district'?'33.17.01':($level==='regency'?'33.17':'33')) ?>"></label><label>Nama resmi <span class="required">*</span><input name="name" value="<?= h($region['name']??'') ?>" required></label><?php if ($level!=='province'): ?><?php $selector_id='region-parent-form';$selector_name='parent_id';$selector_until=array('regency'=>'province','district'=>'regency','village'=>'district')[$level];$selected_ids[$selector_until]=$parent['id']??null;$this->load->view('regions/selector',compact('selector_id','selector_name','selector_until','selected_ids','provinces')); ?><?php endif; ?><?php if ($level==='village'): ?><label>Jenis wilayah<select name="village_type"><option value="desa" <?= ($region['village_type']??'')==='desa'?'selected':'' ?>>Desa</option><option value="kelurahan" <?= ($region['village_type']??'')==='kelurahan'?'selected':'' ?>>Kelurahan</option></select></label><?php endif; ?><label class="form-full">Nomor keputusan / sumber <span class="required">*</span><input name="source_ref" value="<?= h($region && $region['source_version_id'] ? ($this->db->get_where('source_versions',array('id'=>$region['source_version_id']))->row('reference_no')) : '') ?>" required placeholder="Contoh: 300.2.2-2138/2025"></label><label class="check-label form-full"><input type="checkbox" name="active" value="1" <?= !isset($region) || $region['active']?'checked':'' ?>> Aktif dan tersedia di pilihan wilayah</label></div><div class="form-actions"><button class="button button-dark" type="submit">Simpan wilayah <span>→</span></button><a class="button button-quiet" href="<?= site_url('admin/wilayah/'.$level) ?>">Batal</a></div></form></section>
